const payload = $input.first().json.body || $input.first().json;
const jobId = String(payload.jobId || payload.job_id || '').trim();
if (!/^[0-9a-zA-Z_-]{1,64}$/.test(jobId)) throw new Error('jobId inválido.');
return { json: { jobId, preview: Boolean(payload.preview) } };

const input = $input.first();
const request = $('Ler Pedido').first().json;
const text = input.json.jobText;
if (!text) throw new Error('job.json não encontrado.');
const job = JSON.parse(text);
return { json: { ...job, preview: request.preview } };

const job = $('Ler Job').first().json || {};
const settings = job.settings || {};
const jobId = String(job.jobId || $('Ler Pedido').first().json.jobId);
const preview = Boolean(job.preview);
const templates = (Array.isArray(settings.templates) ? settings.templates : []).map((name) => String(name).trim()).filter(Boolean);
if (!templates.length) throw new Error('Job sem templates selecionados.');
const available = $('Listar Backgrounds').all().map((item) => item.json.Key || item.json.key || '').filter((key) => /.(mp4|mov|webm|m4v)$/i.test(key)).sort();
const mode = String(settings.background_mode || 'none').toLowerCase();
const selected = Array.isArray(settings.background_keys) ? settings.background_keys : [];
let backgrounds;
let renderMode;
let varied = false;
if (mode === 'none') { backgrounds = [null]; renderMode = 'none'; }
else if (mode === 'source') {
  if (!String(job.source?.mime || '').toLowerCase().startsWith('video/')) throw new Error('O job usou o arquivo enviado como fundo, mas o upload é áudio.');
  backgrounds = [null]; renderMode = 'source';
}
else if (mode === 'folder_all') { backgrounds = available; renderMode = 'fixed'; }
else if (mode === 'folder_selected' || mode === 'folder_varied') { backgrounds = selected.filter((key) => available.includes(key)); renderMode = 'fixed'; varied = mode === 'folder_varied'; }
else if (mode === 'fixed') { backgrounds = selected.slice(0, 1).filter((key) => available.includes(key)); renderMode = 'fixed'; }
else { backgrounds = [null]; renderMode = 'none'; }
if (!backgrounds.length) throw new Error('Nenhum background encontrado para o job.');
const sourceWords = (job.timeline && Array.isArray(job.timeline.words) && job.timeline.words.length ? job.timeline.words : (job.draft && Array.isArray(job.draft.words) ? job.draft.words : []))
  .filter((word) => word && (word.word || word.text))
  .map((word) => ({ word: String(word.word || word.text), start: Number(word.start), end: Number(word.end) }))
  .filter((word) => Number.isFinite(word.start) && Number.isFinite(word.end) && word.end > word.start)
  .sort((a, b) => a.start - b.start);
if (!sourceWords.length) throw new Error('Job sem palavras válidas na timeline.');
const words = sourceWords;
const duration = Number(job.source?.duration || job.draft?.duration || (words[words.length - 1].end + 0.5));
const syncRevision = Number(job.timeline?.revision || 0);
const filename = job.source?.filename || 'input';
const jobStartedAt = job.created_at || new Date().toISOString();
let selectedTemplates = templates;
let selectedBackgrounds = backgrounds;
if (preview) { selectedTemplates = templates.slice(0, 1); selectedBackgrounds = backgrounds.slice(0, 1); if (!selectedBackgrounds.length) selectedBackgrounds = [null]; }
const slugify = (value) => String(value || '').split('/').pop().replace(/.[^.]+$/, '').replace(/[^a-zA-Z0-9._-]+/g, '-');
function shuffle(list) { const copy = [...list]; for (let i = copy.length - 1; i > 0; i -= 1) { const j = Math.floor(Math.random() * (i + 1)); [copy[i], copy[j]] = [copy[j], copy[i]]; } return copy; }
const buildItem = (background, runIndex, templateName) => {
  const templateFile = templateName.toLowerCase().endsWith('.html') ? templateName : templateName + '.html';
  const templateSlug = slugify(templateFile);
  const backgroundSlug = background ? slugify(background) : renderMode === 'source' ? 'source' : 'nobg';
  return { json: {
    run_index: runIndex, background_mode: renderMode,
    background_file: renderMode === 'source' ? filename : background || '',
    background_key: background || '', template_file: templateFile, template_name: templateSlug,
    template_style: '{}', transcript_data: JSON.stringify(words), original_filename: filename,
    source_video_key: job.source?.key || '', bucket: 'lyrics',
    s3_key: jobId + '_r' + syncRevision + '_' + runIndex + '_' + backgroundSlug + '_' + templateSlug + '.mp4',
    duration, word_count: words.length, language: job.lyrics?.language || 'pt',
    segmentation_mode: job.lyrics?.segmentation_mode || 'lyrics',
    output_aspect: settings.output_aspect || '9:16', output_quality: settings.output_quality || '1080',
    fill_mode: settings.fill_mode || 'contain', job_started_at: jobStartedAt, job_id: jobId,
    sync_revision: String(syncRevision), is_preview: preview ? 'true' : 'false',
    s3_public_base_url: 'http://localhost:8333',
  } };
};
if (varied) {
  let pool = shuffle(selectedTemplates); let cursor = 0;
  return selectedBackgrounds.map((background, index) => { if (cursor >= pool.length) { pool = shuffle(selectedTemplates); cursor = 0; } return buildItem(background, index, pool[cursor++]); });
}
return selectedBackgrounds.flatMap((background, backgroundIndex) => selectedTemplates.map((templateName, templateIndex) => buildItem(background, backgroundIndex * selectedTemplates.length + templateIndex, templateName)));

