      backgroundMode = 'fixed';
      backgroundKey = available[0];
      backgroundFile = available[0];
    }
  }
}
return items.map((item) => ({
  json: {
    ...item.json,
    background_mode: backgroundMode,
    background_key: backgroundKey,
    background_file: backgroundFile,
  },
}));

const job = $('Ler Job').first().json || {};
const timeline = job.timeline || {};
const draft = job.draft || {};
const source = (Array.isArray(timeline.words) && timeline.words.length
  ? timeline.words
  : (Array.isArray(draft.words) ? draft.words : []));
const hasLine = source.some((word) => word && word.line !== null && word.line !== undefined && word.line !== '');
if (!hasLine && Array.isArray(timeline.lines) && timeline.lines.length) {
  timeline.lines.forEach((line, lineIndex) => {
    const start = Number(line.word_start);
    const end = Number(line.word_end);
    if (!Number.isFinite(start) || !Number.isFinite(end)) return;
    for (let index = start; index < end && index < source.length; index += 1) {
      if (source[index] && (source[index].line === null || source[index].line === undefined)) {
        source[index] = { ...source[index], line: lineIndex };
      }
    }
  });
}
const words = source
  .filter((word) => word && (word.word || word.text))
  .map((word) => ({
    word: String(word.word || word.text),
    start: Number(word.start),
    end: Number(word.end),
    line: word.line === null || word.line === undefined || word.line === ''
      ? null
      : (Number.isFinite(Number(word.line)) ? Number(word.line) : null),
  }))
  .filter((word) => Number.isFinite(word.start) && Number.isFinite(word.end) && word.end > word.start)
  .sort((a, b) => a.start - b.start);
if (!words.length) return $input.all();
const transcript = JSON.stringify(words);
return $input.all().map((item) => ({ json: { ...item.json, transcript_data: transcript } }));

