return [{ json: { jobId, executionId } }];

const info = $('Verificar Lote').first()?.json || {};
const jobId = String(info.jobId || '');
const executionId = String(info.executionId || '');
const rows = $input.all().map((item) => item.json || {});
const current = rows.filter((row) => String(row.execution_id || '') === executionId);
const currentSuccess = current.filter((row) => row.status === 'success');
const currentErrors = current.filter((row) => row.status === 'error').length;
if (!currentSuccess.length || currentErrors) return [];
const currentKeys = new Set(currentSuccess.map((row) => String(row.s3_key || '')).filter(Boolean));
const previous = rows.filter((row) => {
  const rowJob = String(row.job_id || '');
  const rowExecution = String(row.execution_id || '');
  const rowPreview = String(row.is_preview || '') === 'true';
  return rowJob === jobId && rowExecution !== executionId && !rowPreview;
});
return previous.map((row) => ({ json: {
  id: row.id,
  s3_key: String(row.s3_key || ''),
  bucket: row.bucket || 'lyrics',
  execution_id: row.execution_id || '',
} }));
